urlset:
{%- set pages = [
  ('home',              '1.0', 'weekly'),
  ('book_rooms',        '0.9', 'daily'),
  ('workshops_public',  '0.9', 'weekly'),
  ('restaurant_info',   '0.8', 'weekly'),
  ('events_info',       '0.7', 'monthly'),
  ('events_weddings',   '0.7', 'monthly'),
  ('events_private',    '0.6', 'monthly'),
  ('events_photoshoots','0.6', 'monthly'),
  ('facilities',        '0.7', 'monthly'),
  ('restoration_page',  '0.8', 'monthly'),
  ('story',             '0.7', 'monthly'),
  ('gallery',           '0.6', 'weekly'),
  ('press',             '0.5', 'monthly'),
  ('whats_on',          '0.6', 'weekly'),
  ('contact_page',      '0.5', 'yearly'),
  ('terms',             '0.2', 'yearly')
] -%}
{%- for endpoint, priority, freq in pages %}
{%- if endpoint in url_map %}

    {{ url_for(endpoint, _external=True) }}
    {{ freq }}
    {{ priority }}
    {%- if lastmod %}{{ lastmod }}{% endif %}
    {%- for code in (languages or ['en']) %}

    {%- endfor %}

{%- endif %}
{%- endfor %}
{#- Each room gets its own entry — they are the pages that should rank. -#}
{%- for r in (rooms or []) %}

    {{ url_for('book_room', room_id=r['id'], _external=True) }}
    weekly
    0.8

{%- endfor %}
